import sys, optax
sys.path.append('storage/zephyr/submissions')
from ray import tune
from double_step_time_core import create_network as base_create_network

BASE_SEED = 42

def _define_hyperparameters():
    return {
        'learning_rate': tune.choice([5e-4]),  # matches seed-42 wd=0.0 baseline
        'entropy_coef': tune.choice([0.01]),
        'value_loss_coef': tune.choice([0.5]),
        'cnn_features_1': tune.choice([32]),
        'cnn_features_2': tune.choice([64]),
        'conv_lstm_features': tune.choice([64]),
        'dilation': tune.choice([6]),
        'bottleneck_ratio': tune.choice([0.28]),
    }

def create_network(hparams):
    return base_create_network(hparams)

def create_optimizer(learning_rate: float = 5e-4):
    total_updates = 39062
    warmup_steps = max(1, int(0.025 * total_updates))  # 2.5% warmup
    schedule = optax.join_schedules(
        schedules=[
            optax.linear_schedule(init_value=0.0, end_value=learning_rate, transition_steps=warmup_steps),
            optax.constant_schedule(learning_rate),
        ],
        boundaries=[warmup_steps],
    )
    return optax.chain(optax.clip_by_global_norm(1.0),
                       optax.adamw(learning_rate=schedule, weight_decay=0.0))
